1	/**
2	 * Runs an e2e suite: build (with dev UI), snapshot the fixture vault, run
3	 * WebdriverIO, then report and revert whatever the run changed — in a `finally`,
4	 * so cleanup happens even when the suite throws.
5	 *
6	 * A Node script rather than a chain in package.json because that chain needed
7	 * `VAR=1`, `{ ...; }`, `$?` and `[ ... ]`, all POSIX-only: on Windows' default
8	 * cmd.exe shell the scripts failed before reaching WebdriverIO. Windows is not a
9	 * supported dev platform today, so this is mostly for future contributors — but
10	 * it also buys a real `finally`, which the shell version did not have.
11	 *
12	 *   node scripts/run-e2e.mjs [desktop|mobile] [--group <name>]
13	 *   node scripts/run-e2e.mjs --list-groups          # JSON, for the CI matrix
14	 *
15	 * `--group` restricts the run to one group of specs (see `./spec-groups.mjs`);
16	 * without it every spec runs. `--list-groups` prints the names as JSON, which
17	 * is how the CI matrix is built.
18	 */
19	
20	import { spawnSync } from 'node:child_process';
21	import { fileURLToPath } from 'node:url';
22	import * as path from 'node:path';
23	import { binPath } from './bin-path.mjs';
24	import { EXCLUSIVE_GROUPS, specGroups } from './spec-groups.mjs';
25	
26	const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
27	
28	const argv = process.argv.slice(2);
29	if (argv.includes('--list-groups')) {
30	  console.log(JSON.stringify(Object.keys(specGroups())));
31	  process.exit(0);
32	}
33	
34	// Validated, not treated as "mobile or else": CI names the job, the cache and
35	// the artifact after this, so a typo would file a desktop run under them.
36	const platform = argv[0]?.startsWith('--') ? 'desktop' : (argv[0] ?? 'desktop');
37	if (platform !== 'desktop' && platform !== 'mobile') {
38	  console.error(`[e2e] unknown platform ${JSON.stringify(platform)}. Expected 'desktop' or 'mobile'.`);
39	  process.exit(1);
40	}
41	const mobile = platform === 'mobile';
42	const group = argv[argv.indexOf('--group') + 1];
43	
44	// Resolved here rather than handed to wdio as a glob, so an unknown group
45	// fails instead of running zero specs and reporting success.
46	const specArgs = [];
47	if (argv.includes('--group')) {
48	  const groups = specGroups();
49	  const specs = groups[group];
50	  if (!specs) {
51	    console.error(
52	      `[e2e] unknown group ${JSON.stringify(group)}. Known groups: ${Object.keys(groups).join(', ')}`,
53	    );
54	    process.exit(1);
55	  }
56	  specArgs.push(...specs.flatMap((spec) => ['--spec', spec]));
57	}
58	
59	/**
60	 * Whether this run will execute any spec from an exclusive group — true for the
61	 * group itself, and true for the whole suite, which contains it.
62	 */
63	const runsExclusiveSpecs = argv.includes('--group')
64	  ? EXCLUSIVE_GROUPS.has(group)
65	  : Object.keys(specGroups()).some((g) => EXCLUSIVE_GROUPS.has(g));
66	// Resolved before the build, so a missing install fails loudly and changes nothing.
67	const wdio = binPath('wdio');
68	
69	/** Exit status of a step, with output passed straight through. */
70	const run = (cmd, args, env) =>
71	  spawnSync(cmd, args, { cwd: root, stdio: 'inherit', env: { ...process.env, ...env } }).status ?? 1;
72	
73	const build = run(process.execPath, ['esbuild.config.mjs', 'production', '--dev']);
74	if (build !== 0) process.exit(build);
75	
76	// The hub fixture is generated, not tracked: several hundred near-identical
77	// notes whose only property is bulk would be noise in every diff. Generating it
78	// here is what makes that trade safe — it is deterministic (fixed seed), so the
79	// corpus is the same on every machine, and without this step CI simply had no
80	// hub. S5 then measured a note with eight backlinks and would have reported it
81	// as a hub's cost, which is worse than failing.
82	//
83	// Before the drift snapshot, so the generated files are part of the baseline
84	// rather than showing up as changes the run has to explain.
85	const hub = run(process.execPath, ['scripts/gen-backlink-hub.mjs']);
86	if (hub !== 0) process.exit(hub);
87	
88	const drift = (...args) => run(process.execPath, ['scripts/check-vault-drift.mjs', ...args]);
89	if (drift('--snapshot') !== 0) process.exit(1);
90	
91	let suite = 1;
92	try {
93	  suite = run(
94	    wdio,
95	    ['run', mobile ? 'e2e/wdio.mobile-emulation.conf.mts' : 'e2e/wdio.conf.mts', ...specArgs],
96	    {
97	      ...(mobile ? { OBSIDIAN_E2E_MOBILE: '1' } : {}),
98	      // A run that includes specs contending for a machine-global resource goes
99	      // one instance at a time, whatever the caller asked for. The constraint
100	      // belongs to the specs, not to whoever happens to be invoking them.
101	      //
102	      // "Includes" rather than "is": with no `--group` the run is the whole
103	      // suite, which contains the exclusive specs and had the same race — the
104	      // guard only fired on the `--group` path, so the documented full-suite
105	      // invocation was exactly the one it did not cover. CI never took that path
106	      // (its matrix passes a group per job), which is why the hole survived.
107	      //
108	      // This does serialise a full local run. That is the honest cost: the
109	      // alternative is two wdio invocations per run, and nothing's throughput
110	      // depends on a path CI does not use.
111	      ...(runsExclusiveSpecs ? { E2E_MAX_INSTANCES: '1' } : {}),
112	    },
113	  );
114	} finally {
115	  // Keep the suite's status; if it passed but cleanup failed, fail with 1 so a
116	  // dirty vault is never reported as success.
117	  const cleanup = drift();
118	  process.exitCode = suite !== 0 ? suite : cleanup !== 0 ? 1 : 0;
119	}
