1	/** The parts of the two wdio configs that must stay identical — see
2	 * `./obsidian-target.mts` for what happened last time they drifted. */
3	
4	import * as fsp from 'node:fs/promises';
5	import * as path from 'node:path';
6	import { browser } from '@wdio/globals';
7	
8	/**
9	 * How many Obsidian instances run at once; 1 unless E2E_MAX_INSTANCES says
10	 * otherwise. Each is a full Electron renderer, and `waitBudget` in
11	 * ./helpers.ts widens the harness timeouts off this value, so raising it
12	 * changes how the suite behaves and not just how fast it finishes.
13	 */
14	export function maxInstances(): number {
15	  const raw = process.env.E2E_MAX_INSTANCES?.trim();
16	  if (!raw) return 1;
17	  const n = Number(raw);
18	  if (!Number.isInteger(n) || n < 1) {
19	    throw new Error(`E2E_MAX_INSTANCES must be a positive integer, got ${JSON.stringify(raw)}`);
20	  }
21	  return n;
22	}
23	
24	/** Where `screenshotOnFailure` writes. CI uploads this only when a job fails. */
25	export const FAILURE_SCREENSHOT_DIR = path.join(
26	  process.cwd(),
27	  '.obsidian-cache',
28	  'failure-screenshots',
29	);
30	
31	/** `a/b: c` -> `a-b-c`, so a test title is safe as a file name. */
32	function slugify(text: string): string {
33	  return text
34	    .replace(/[^a-zA-Z0-9]+/g, '-')
35	    .replace(/^-+|-+$/g, '')
36	    .slice(0, 120);
37	}
38	
39	/**
40	 * An `afterTest` hook that captures the screen for a failing test.
41	 *
42	 * A capture failure is swallowed: when the session itself has died, the useful
43	 * error is the test's own, not "could not screenshot".
44	 */
45	export function screenshotOnFailure(label: string) {
46	  return async function (
47	    test: { title: string; parent: string },
48	    _context: unknown,
49	    { passed }: { passed: boolean },
50	  ): Promise<void> {
51	    if (passed) return;
52	    try {
53	      await fsp.mkdir(FAILURE_SCREENSHOT_DIR, { recursive: true });
54	      const name = slugify(`${label}-${test.parent}-${test.title}`);
55	      await browser.saveScreenshot(path.join(FAILURE_SCREENSHOT_DIR, `${name}.png`));
56	    } catch (e) {
57	      console.warn(`[e2e] could not capture a failure screenshot for "${test.title}": ${String(e)}`);
58	    }
59	  };
60	}
