1	/**
2	 * Which Obsidian build the e2e suites run against, and where it is cached.
3	 *
4	 * Shared by `wdio.conf.mts` and `wdio.mobile-emulation.conf.mts` rather than
5	 * duplicated: the two configs had drifted, and the mobile one honored neither
6	 * `OBSIDIAN_VERSION` nor a configurable cache, so pinning a version silently
7	 * applied to the desktop suite only — the exact "two things that look the same
8	 * and aren't" failure this module exists to prevent.
9	 */
10	
11	import { existsSync, readFileSync } from 'node:fs';
12	import * as os from 'node:os';
13	import * as path from 'node:path';
14	import { obsidianBetaAvailable } from 'wdio-obsidian-service';
15	
16	/** One cache for the availability probe, the service, and `obsidian:fetch`.
17	 * `OBSIDIAN_CACHE` (the launcher's own env var) wins, so a shared machine-wide
18	 * cache still works; otherwise repo-local. */
19	export function resolveCacheDir(root: string): string {
20	  return process.env.OBSIDIAN_CACHE
21	    ? path.resolve(process.env.OBSIDIAN_CACHE)
22	    : path.join(root, '.obsidian-cache');
23	}
24	
25	/**
26	 * `OBSIDIAN_VERSION`, treated as unset when blank. GitHub Actions expands an
27	 * absent `workflow_dispatch` input to the EMPTY STRING rather than leaving the
28	 * variable undefined, so `??` alone would pin `browserVersion` to `''` on every
29	 * ordinary pull-request run and fail before launch.
30	 */
31	export function pinnedVersion(): string | undefined {
32	  return process.env.OBSIDIAN_VERSION?.trim() || undefined;
33	}
34	
35	/**
36	 * Is this version downloadable without Catalyst credentials? Reads the launcher's
37	 * own version metadata, which marks insider builds `isBeta` and gives them only
38	 * the `releases.obsidian.md` endpoint; public releases carry GitHub asset URLs.
39	 * Unknown or unreadable metadata answers `true`, so an uncertain case is left to
40	 * the service rather than blocked here.
41	 */
42	function isPubliclyDownloadable(version: string, cacheDir: string): boolean {
43	  try {
44	    const raw = readFileSync(path.join(cacheDir, 'obsidian-versions.json'), 'utf-8');
45	    const parsed: unknown = JSON.parse(raw);
46	    const list = Array.isArray(parsed)
47	      ? parsed
48	      : ((parsed as { versions?: unknown[] }).versions ?? []);
49	    const entry = (list as { version?: string; isBeta?: boolean; downloads?: Record<string, string> }[]).find(
50	      (v) => v.version === version,
51	    );
52	    if (!entry) return true;
53	    const hasPublicAsset = Object.values(entry.downloads ?? {}).some((u) => u.includes('github.com'));
54	    return !entry.isBeta || hasPublicAsset;
55	  } catch {
56	    return true;
57	  }
58	}
59	
60	/**
61	 * Fails fast, and accurately, when a pinned version cannot be obtained.
62	 *
63	 * Deliberately narrow: it fires only for a version that is BOTH absent from the
64	 * cache AND insider-only. A publicly-downloadable pin is left alone so
65	 * `wdio-obsidian-service` can fetch it — an earlier version threw on any
66	 * uncached pin, which made the `workflow_dispatch` version input useless on CI,
67	 * where the cache starts empty and the whole point is to download the pin.
68	 *
69	 * For the insider case it names the real cause, including "BUT it IS cached at
70	 * <the launcher CLI's default>", because a download that SUCCEEDED into the
71	 * wrong directory otherwise surfaces as "Insiders account is required" — a cache
72	 * path problem wearing a credentials costume.
73	 */
74	export function assertCached(version: string, cacheDir: string): void {
75	  if (!/^\d+\.\d+\.\d+$/.test(version)) return; // 'latest'/'latest-beta' resolve later
76	  const asar = path.join(cacheDir, 'obsidian-app', `obsidian-${version}.asar`);
77	  if (existsSync(asar) || existsSync(`${asar}.gz`)) return;
78	
79	  // Checked BEFORE the downloadable test, because the wrong-cache case is the one
80	  // this diagnostic exists for and it was skipping itself: a user who downloaded
81	  // into the launcher's default cache has no `obsidian-versions.json` in the
82	  // repo-local one either, so `isPubliclyDownloadable` fell back to `true`, this
83	  // returned early, and they got the generic service error the message was
84	  // written to replace. If the build is sitting in the other cache, say so
85	  // whatever the metadata does or does not know.
86	  const elsewhere = path.join(os.homedir(), '.obsidian-cache', 'obsidian-app', `obsidian-${version}.asar`);
87	  const foundElsewhere = existsSync(elsewhere) || existsSync(`${elsewhere}.gz`);
88	  if (!foundElsewhere && isPubliclyDownloadable(version, cacheDir)) return; // the service can fetch it
89	
90	  throw new Error(
91	    `Obsidian ${version} is not in this harness's cache.\n` +
92	      `  looked in: ${asar}\n` +
93	      (foundElsewhere
94	        ? `  BUT it IS cached at: ${elsewhere}\n` +
95	          `  That is the obsidian-launcher CLI's default cache, not this harness's. Either:\n` +
96	          `    OBSIDIAN_CACHE=~/.obsidian-cache OBSIDIAN_VERSION=${version} npm run test:e2e\n` +
97	          `  or re-fetch into the repo-local cache:\n` +
98	          `    npm run obsidian:fetch -- -v ${version}\n`
99	        : `  fetch it with:  npm run obsidian:fetch -- -v ${version}\n` +
100	          `  (prompts for Catalyst credentials; every 1.13.x is currently insider-only)\n`),
101	  );
102	}
103	
104	/**
105	 * Resolves the target build and announces it. The banner names the fallback AS
106	 * a fallback: Q21 lost three rounds to a silent version mismatch and Q27 several
107	 * more, both times with a harness that was internally consistent and green. It
108	 * prints in the launcher process only — the config is re-loaded in every worker,
109	 * and 18 copies is noise that trains you to ignore it.
110	 */
111	export async function resolveObsidianTarget(
112	  root: string,
113	  label: string,
114	): Promise<{ browserVersion: string; cacheDir: string }> {
115	  const cacheDir = resolveCacheDir(root);
116	  const pinned = pinnedVersion();
117	  const betaAvailable = await obsidianBetaAvailable({ cacheDir });
118	  const browserVersion = pinned ?? (betaAvailable ? 'latest-beta' : 'latest');
119	
120	  assertCached(browserVersion, cacheDir);
121	
122	  if (process.env.WDIO_WORKER_ID === undefined) {
123	    const note =
124	      pinned !== undefined
125	        ? `pinned via OBSIDIAN_VERSION=${pinned}`
126	        : betaAvailable
127	          ? 'current beta (cached or credentialed)'
128	          : 'FALLBACK to latest stable — no beta cached, so this may NOT match the build a bug was reported on';
129	    console.log(`\n[e2e${label}] Obsidian target: ${browserVersion} — ${note}\n`);
130	  }
131	  return { browserVersion, cacheDir };
132	}
