1	/**
2	 * Reports and reverts the drift an e2e run leaves in the fixture vault —
3	 * and ONLY that drift.
4	 *
5	 * A full suite reliably mutates `test-vault/`: Obsidian's own table
6	 * auto-alignment reformats fixture tables, `.obsidian/` config picks up keys,
7	 * the plugin's data.json accumulates outlinePaths, and a Journal note has
8	 * gained hard line breaks from a keypress meant for a scratch note reached
9	 * through restored workspace state. That last class is the dangerous one — it
10	 * changes a fixture's PARSE SHAPE, so a later test measures something different
11	 * with nothing failing. It also, once, got swept into a commit by a broad
12	 * `git add -A` and became the baseline.
13	 *
14	 * Usage (see the `test:e2e` scripts):
15	 *
16	 *     node scripts/check-vault-drift.mjs --snapshot   # before the suite
17	 *     node scripts/check-vault-drift.mjs              # after
18	 *
19	 * The snapshot records each pre-existing dirty path's CONTENT, not just its name.
20	 * Names alone could not honor the safety claim: if the suite then edited such a
21	 * path — or `resetVault()` deleted an untracked draft — the post-run pass either
22	 * left the suite's version in place or saw no path at all, and the original was
23	 * gone either way. With the bytes, it can be put back.
24	 *
25	 * Snapshot-based rather than "restore everything dirty", because the blunt
26	 * version destroys uncommitted work: editing a fixture by hand and then running
27	 * the suite would silently revert the edit. Only paths that were CLEAN before
28	 * the run are restored; anything already modified is reported and left alone.
29	 * With no snapshot (a direct invocation) it reports and reverts nothing, since
30	 * it cannot tell the two apart.
31	 *
32	 * The snapshot is CONSUMED — deleted as soon as it is read — so it can only
33	 * ever describe the run it was taken for. Leaving it behind meant a later
34	 * direct invocation would treat a stale file as a valid baseline and revert
35	 * fixture edits made since, which is exactly the data loss the snapshot exists
36	 * to prevent, arriving by a different route.
37	 */
38	
39	import { execFileSync } from 'node:child_process';
40	import { existsSync, mkdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
41	import { fileURLToPath } from 'node:url';
42	import * as path from 'node:path';
43	
44	const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
45	const SNAPSHOT = path.join(root, 'node_modules/.cache/vault-drift-baseline.json');
46	
47	const git = (...args) => execFileSync('git', args, { cwd: root, encoding: 'utf-8' });
48	
49	/**
50	 * Paths under test-vault that differ from HEAD right now, each tagged with
51	 * whether git tracks it.
52	 *
53	 * The distinction is load-bearing: `git checkout` cannot restore an UNTRACKED
54	 * path — it exits non-zero with "pathspec did not match any file known to git"
55	 * — and the suite creates `Scratch/*.md` notes that are untracked and not
56	 * ignored. Passing one to checkout would fail the cleanup and, with the exit-code
57	 * handling in the `test:e2e` scripts, fail an otherwise-passing run while leaving
58	 * the vault dirty.
59	 *
60	 * `--untracked-files=all` matters just as much. Git COLLAPSES untracked
61	 * directories by default, so one hand-written `Scratch/draft.md` makes both
62	 * snapshots report only `Scratch/`, and every note the suite then creates in that
63	 * directory is mistaken for pre-existing work and left behind. Listing files
64	 * individually is what lets the baseline tell a draft from run output.
65	 */
66	function dirtyEntries() {
67	  // `-z` is not optional. Without it git C-QUOTES any non-ASCII path, and this
68	  // vault has tracked fixtures that trigger it — `Notes/Reading – …`, `People/
69	  // Tomás Rivera.md`. Stripping the surrounding quotes leaves the escapes
70	  // (`Reading \342\200\223 …`), so a later `git checkout` gets a path that does
71	  // not exist, cleanup fails, and — since a failed cleanup now fails the run —
72	  // the suite reports failure with the fixture still dirty. `-z` returns path
73	  // bytes verbatim, NUL-delimited.
74	  const out = git('status', '--porcelain', '-z', '--untracked-files=all', '--', 'test-vault');
75	  const fields = out.split('\0');
76	  const entries = [];
77	  for (let i = 0; i < fields.length; i++) {
78	    const field = fields[i];
79	    if (field.length < 4) continue; // trailing empty field
80	    const code = field.slice(0, 2);
81	    entries.push({ path: field.slice(3), code, untracked: code === '??' });
82	    // A rename or copy emits its ORIGINAL path as a separate following field.
83	    // Either COLUMN can carry it, so test both: with `startsWith` an unstaged
84	    // ` R` slipped through and the original-path field was then parsed as if it
85	    // were another status entry, putting a truncated bogus path into the snapshot
86	    // and cleanup sets. (`includes('D')` below already tests both columns —
87	    // this was inconsistent with its own neighbour.)
88	    if (code.includes('R') || code.includes('C')) i += 1;
89	  }
90	  return entries;
91	}
92	
93	function dirtyPaths() {
94	  return dirtyEntries().map((e) => e.path);
95	}
96	
97	if (process.argv.includes('--snapshot')) {
98	  mkdirSync(path.dirname(SNAPSHOT), { recursive: true });
99	  const baseline = dirtyEntries().map((e) => {
100	    let content = null;
101	    try {
102	      content = readFileSync(path.join(root, e.path), 'utf-8');
103	    } catch {
104	      /* a directory, or deleted before the run */
105	    }
106	    // `deleted` is kept separately from `content === null`: a path the developer
107	    // DELETED before the run is restored from git by `resetVault()`, at which
108	    // point it is clean and no longer appears in the post-run diff at all — so
109	    // without recording the intent, cleanup silently resurrects it.
110	    return { path: e.path, content, deleted: e.code.includes('D') };
111	  });
112	  writeFileSync(SNAPSHOT, JSON.stringify(baseline));
113	  if (baseline.length > 0) {
114	    console.log(
115	      `[vault-drift] ${baseline.length} file(s) already modified before the run — these will be left alone:`,
116	    );
117	    for (const e of baseline) console.log(`  ${e.path}`);
118	  }
119	  process.exit(0);
120	}
121	
122	if (!existsSync(SNAPSHOT)) {
123	  console.log('[vault-drift] no pre-run snapshot; reporting only, restoring nothing');
124	  for (const f of dirtyPaths()) console.log(`  dirty: ${f}`);
125	  process.exit(0);
126	}
127	
128	const baseline = JSON.parse(readFileSync(SNAPSHOT, 'utf-8'));
129	const before = new Set(baseline.map((e) => e.path));
130	rmSync(SNAPSHOT, { force: true }); // consumed: never valid for a later run
131	
132	// Put back anything the run changed UNDER a path that was already dirty. Without
133	// this the safety claim was only about paths the run created.
134	let rescued = 0;
135	for (const entry of baseline) {
136	  const abs = path.join(root, entry.path);
137	  if (entry.deleted) {
138	    // Re-delete: the run (or resetVault) put it back.
139	    if (existsSync(abs)) {
140	      rmSync(abs, { force: true });
141	      rescued += 1;
142	    }
143	    continue;
144	  }
145	  if (entry.content === null) continue;
146	  let current = null;
147	  try {
148	    current = readFileSync(abs, 'utf-8');
149	  } catch {
150	    /* the run deleted it */
151	  }
152	  if (current === entry.content) continue;
153	  mkdirSync(path.dirname(abs), { recursive: true });
154	  writeFileSync(abs, entry.content);
155	  rescued += 1;
156	}
157	if (rescued > 0) console.log(`[vault-drift] restored ${rescued} of your pre-existing edit(s) that the run changed`);
158	const now = dirtyEntries();
159	const introduced = now.filter((e) => !before.has(e.path));
160	const preexisting = now.filter((e) => before.has(e.path));
161	
162	if (introduced.length === 0) {
163	  console.log('[vault-drift] clean');
164	} else {
165	  console.log(`[vault-drift] the e2e run touched ${introduced.length} path(s) in test-vault:`);
166	  for (const e of introduced) console.log(`  ${e.untracked ? 'new ' : 'mod '}${e.path}`);
167	
