import { execFileSync, spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import * as path from 'node:path';
import { specGroups } from './spec-groups.mjs';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const composeFile = path.join(root, 'e2e', 'docker', 'docker-compose.yml');

/**
 * A git WORKTREE's `.git` is a file pointing at an absolute host path
 * (`<main checkout>/.git/worktrees/<name>`) — bind-mounting the worktree
 * alone gives the container that pointer with nothing at the far end, so
 * every git-invoking step (the build stamp in esbuild.config.mjs included)
 * fails with "not a git repository". Bind-mounting the real git dir at the
 * SAME absolute path resolves the pointer without needing the main checkout
 * anywhere else in the container. A plain (non-worktree) checkout's
 * `--git-common-dir` is just `.git` under the already-mounted root, so this
 * is a no-op there.
 */
function extraGitVolumeArgs() {
  const commonDir = path.resolve(root, execFileSync('git', ['rev-parse', '--git-common-dir'], {
    cwd: root,
    encoding: 'utf-8',
  }).trim());
  if (commonDir === path.join(root, '.git')) return [];
  return ['-v', `${commonDir}:${commonDir}:ro`];
}

