import { expect } from '@wdio/globals';
import * as fsp from 'node:fs/promises';
import { vaultFilePath } from '../helpers.js';

describe('scratch negative control', function () {
  it('tampers with a tracked vault fixture (exercises drift cleanup)', async function () {
    const p = vaultFilePath('Notes/Sourdough Log.md');
    const before = await fsp.readFile(p, 'utf-8');
    await fsp.writeFile(p, before + '\ntampered by scratch spec\n');
    expect(true).toBe(true);
  });
});
